ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(txt_Motivo_DSC_1.Text) && CountIf(
        datos_DSC,
        !aprobado
    ) > 0,
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "Debe indicar el motivo del rechazo de los items"
            }
        }
    ), 
    IsBlank(
        LookUp(
            Compras_NoMarcadas,
            NSolicitud = txt_Num_Soli_DSC.Text && Enviado = 0 && Tipo_Envio = "Compras"
        )
    ),
    UpdateContext({Guardando: true});
    ForAll(
        Filter(
            datos_DSC,
            !aprobado
        ),
        Collect(
            Compras_NoMarcadas,
            {
                NSolicitud: Upper(txt_Num_Soli_DSC.Text),
                NFilaSolicitud: ThisRecord.crfb9_linea,
                Enviado: 0,
                Tipo_Envio: "Compras",
                Motivo: txt_Motivo_DSC_1.Text
            }
        )
    );
    RemoveIf(
        Compras_NoMarcadas,
        NSolicitud = txt_Num_Soli_DSC.Text && NFilaSolicitud in Filter(
            datos_DSG,
            aprovado
        ).req_line && Enviado = 1 && Tipo_Envio = "Compras"
    );
    Patch(
        Solicitud_Compras,
        glr_Solicitudes_SC.Selected,
        {
            user: txt_User_DSC.Text,
            total: Value(
                Sum(
                    Filter(
                        datos_DSC,
                        aprobado
                    ),
                    subtotal
                )
            ),
            estado: "Listo"
        }
    );
    ForAll(
        datos_DSC,
        If(
            ThisRecord.aprobado,
            Patch(
                Detalle_Solicitud_Compras,
                With(
                    {line: ThisRecord.crfb9_linea},
                    LookUp(
                        Detalle_Solicitud_Compras,
                        soli_num = Upper(txt_Num_Soli_DSC.Text) && linea = line
                    )
                ),
                {
                    medida: ThisRecord.medida,
                    cantidad: ThisRecord.cantidad,
                    precio: ThisRecord.precio,
                    subtotal: ThisRecord.subtotal,
                    num_vend: ThisRecord.vendNum,
                    provedor: ThisRecord.vendName
                }
            ),
            Remove(
                Detalle_Solicitud_Compras,
                With(
                    {line: ThisRecord.crfb9_linea},
                    LookUp(
                        Detalle_Solicitud_Compras,
                        soli_num = Upper(txt_Num_Soli_DSC.Text) && linea = line
                    )
                )
            )
        )
    );
    Reset(txt_Num_Soli_DSC);
    UpdateContext({showContainer: false});
    Reset(txt_Motivo_DSC_1);
    UpdateContext({Guardando: false});
    Back(),
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "La solicitud seleccionada no puede ser procesada"
            }
        }
    )
);
